package com.example.networkservice.service; import com.example.networkservice.model.*;import com.example.networkservice.repository.ActivationRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.time.*;import java.util.*; @Service public class ActivationService{private final ActivationRepository repo;private final long delay;public ActivationService(ActivationRepository r,@Value("${network.activation-delay-seconds:30}")long d){repo=r;delay=d;}public Activation create(CreateActivationRequest q){if(repo.findByOrderId(q.orderId()).isPresent())throw new IllegalStateException("Activation already exists for this order");Activation a=new Activation();a.setOrderId(q.orderId());a.setCustomerId(q.customerId());a.setPlanId(q.planId());a.setIccid("8944"+Math.abs(UUID.randomUUID().getMostSignificantBits()));a.setStatus(ActivationStatus.QUEUED);a.setRequestedAt(Instant.now());a.setReadyAt(Instant.now().plusSeconds(delay));return repo.save(a);}public List<Activation> list(){return repo.findAll();}public Activation byOrder(String id){return repo.findByOrderId(id).orElseThrow(()->new NoSuchElementException("Activation not found"));}@Scheduled(fixedDelay=2000)public void process(){Instant now=Instant.now();for(Activation a:repo.findByStatusIn(List.of(ActivationStatus.QUEUED,ActivationStatus.ACTIVATING))){if(a.getStatus()==ActivationStatus.QUEUED){a.setStatus(ActivationStatus.ACTIVATING);repo.save(a);}else if(!now.isBefore(a.getReadyAt())){a.setStatus(ActivationStatus.ACTIVE);a.setActivatedAt(now);repo.save(a);}}}}
